import 'dart:io' as io;

import 'package:args/args.dart';
import 'package:path/path.dart' as p;

import 'gen_deps_command.dart' show findRepositoryRoot;
import 'pub_lock.dart';

/// The label used in the "generated by" banner of the output file.
const String pubLockGeneratorLabel = 'engine/src/flutter/tools/bazel_tools/bin/gen_pub_lock.dart';

/// Where `pub.lock.bzl` lives, relative to the repository root.
const String defaultPubLockBzlPath = 'engine/src/flutter/build/bazel/dart/pub.lock.bzl';

/// Generates (or checks) `pub.lock.bzl` from the repository's `pubspec.lock`.
final class GenPubLockCommand {
  GenPubLockCommand._({
    required this.repoRoot,
    required this.check,
    required io.IOSink stdout,
    required io.IOSink stderr,
  }) : _stdout = stdout,
       _stderr = stderr;

  /// Parses [arguments] and creates the command; null (usage printed) when
  /// `--help` is asked for or the arguments are invalid.
  static GenPubLockCommand? fromCommandLine(
    List<String> arguments, {
    io.IOSink? stdout,
    io.IOSink? stderr,
    String? workingDirectory,
  }) {
    final io.IOSink out = stdout ?? io.stdout;
    final io.IOSink err = stderr ?? io.stderr;
    final ArgResults results;
    try {
      results = argParser.parse(arguments);
    } on FormatException catch (e) {
      err
        ..writeln(e.message)
        ..writeln()
        ..writeln(usage);
      return null;
    }
    if (results.flag('help')) {
      out.writeln(usage);
      return null;
    }
    final String? repoRootArgument = results.option('repo-root');
    final String? repoRoot = repoRootArgument != null
        ? p.canonicalize(repoRootArgument)
        : findRepositoryRoot(workingDirectory);
    if (repoRoot == null) {
      err.writeln(
        'Could not find the repository root (the directory containing DEPS) '
        'from the current directory; pass --repo-root.',
      );
      return null;
    }
    return GenPubLockCommand._(
      repoRoot: repoRoot,
      check: results.flag('check'),
      stdout: out,
      stderr: err,
    );
  }

  /// The command-line options.
  static final ArgParser argParser = ArgParser()
    ..addFlag('help', abbr: 'h', negatable: false, help: 'Print this help.')
    ..addFlag(
      'check',
      negatable: false,
      help:
          'Do not write anything; exit with status 1 if the generated file '
          'is missing or out of date (for presubmit).',
    )
    ..addOption(
      'repo-root',
      help:
          'The repository root (the directory containing DEPS and pubspec.lock). '
          'Defaults to the checkout the current directory is in.',
      valueHelp: 'path',
    );

  /// Usage text.
  static String get usage =>
      'Usage: dart bin/gen_pub_lock.dart [options]\n'
      '\n'
      "Generates the Bazel file derived from pubspec.lock and the packages' pubspecs:\n"
      '  $defaultPubLockBzlPath\n'
      '\n'
      '${argParser.usage}';

  /// The repository root.
  final String repoRoot;

  /// Whether to verify the file instead of writing it.
  final bool check;

  final io.IOSink _stdout;
  final io.IOSink _stderr;

  /// Runs the command and returns the process exit code.
  Future<int> run() async {
    final lockFile = io.File(p.join(repoRoot, 'pubspec.lock'));
    if (!lockFile.existsSync()) {
      _stderr.writeln('No pubspec.lock found at ${lockFile.path}.');
      return 1;
    }
    final PubLock lock;
    try {
      lock = PubLock.parse(await lockFile.readAsString(), fileName: lockFile.path);
    } on FormatException catch (e) {
      _stderr.writeln('Failed to parse pubspec.lock: $e');
      return 1;
    }
    final packageConfigFile = io.File(p.join(repoRoot, '.dart_tool', 'package_config.json'));
    if (!packageConfigFile.existsSync()) {
      _stderr.writeln(
        'No ${packageConfigFile.path}: run `pub get` (flutter update-packages) first; the '
        'dependency graph comes from the packages it locates.',
      );
      return 1;
    }
    final PubWorkspace workspace;
    try {
      workspace = PubWorkspace.resolve(
        lock: lock,
        packageConfigJson: await packageConfigFile.readAsString(),
        packageConfigUri: packageConfigFile.absolute.uri,
        repositoryRoot: io.Directory(repoRoot).absolute.uri,
        readPubspec: (Uri pubspec) {
          final file = io.File.fromUri(pubspec);
          return file.existsSync() ? file.readAsStringSync() : null;
        },
      );
    } on FormatException catch (e) {
      _stderr.writeln('Failed to resolve the workspace: $e');
      return 1;
    }
    final String rendered = generatePubLock(lock, workspace, generator: pubLockGeneratorLabel);
    final file = io.File(p.join(repoRoot, defaultPubLockBzlPath));
    final String? existing = file.existsSync() ? await file.readAsString() : null;
    if (existing == rendered) {
      _stdout.writeln(
        'Up to date: $defaultPubLockBzlPath (${lock.hosted.length} hosted packages, '
        '${workspace.packages.length} of the tree)',
      );
      return 0;
    }
    if (check) {
      _stderr.writeln(
        existing == null
            ? 'Missing: $defaultPubLockBzlPath'
            : 'Out of date: $defaultPubLockBzlPath',
      );
      return 1;
    }
    file.parent.createSync(recursive: true);
    await file.writeAsString(rendered);
    _stdout.writeln(
      'Wrote $defaultPubLockBzlPath (${lock.hosted.length} hosted packages, '
      '${workspace.packages.length} of the tree)',
    );
    return 0;
  }
}
